use thinkthen::{Answer, Engine, Question};
let tt = Engine::from_env()?;

// your own scale, 0 to 2: 0.06, 0.99, and 2.0
let urgency = Question::score("How urgent is this?",
    &["Routine.", "Soon.", "Immediate."])?;
for text in ["Please update my mailing address when you can.",
    "Can you send the signed contract by Friday?",
    "Nobody can log in to the site right now."] {
    println!("{} {text}", tt.score(&urgency, text)?.value);
}
